{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C01"],
      "claim": "Absolute oral bioavailability of KNI-272 was 54.97 ± 19.78% in fasting patients after a 10 mg/kg capsule, directly supporting F ≥20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Maraviroc absolute oral bioavailability was 23% in healthy volunteers at 100 mg, supporting F ≥20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C59"],
      "claim": "Niraparib absolute oral bioavailability was 72.7% (90% CI 61.69–83.40) in cancer patients after a 300 mg oral dose versus IV tracer, strongly supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C62"],
      "claim": "Zalcitabine absolute oral bioavailability exceeded 85% in humans for tablets/oral solution, strongly supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C38"],
      "claim": "Elinzanetant oral bioavailability was 36.7% (95% CI 35.4–38) and dose-independent over 40–160 mg, supporting F ≥20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C42"],
      "claim": "Pradigastat absolute oral bioavailability was approximately 40% after oral administration, supporting F ≥20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "MK-8628 was reported to have good oral bioavailability in humans, qualitatively supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Didanosine mean absolute oral bioavailability was 35% in HIV-infected patients, supporting F ≥20% despite formulation-dependent variability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "KNI-272 absolute oral bioavailability was only 12% (range 3.5–25%) in children at 200 mg/m2 with Ora-Plus, a low-F outlier that is pediatric/formulation-specific.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "High-transfer direct absolute F measurements across multiple small-molecule drugs predominantly support F ≥20% (maraviroc 23%, niraparib 73%, zalcitabine >85%, elinzanetant 36.7%, pradigastat ~40%, KNI-272 ~33–55%, didanosine ~35%). The few low-F outliers are pediatric or formulation-specific and do not outweigh the consistent high-F evidence. The query's lipophilic heteroaromatic/piperidine scaffold is consistent with good oral absorption, so predict high.",
  "evidence_gaps": [
    "No direct human absolute bioavailability data for the exact query scaffold.",
    "Some low-F records are pediatric or formulation-specific and may not reflect adult oral absorption of this compound.",
    "One qualitative record (MK-8628) lacks a numeric F value."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

